insert into product (id, slug, name, kind, summary, detail, doc_status, published, sort_order, image_src, image_alt) values ('e3ea02f0-3473-4b3b-95e1-3febc977b5a8', 'vedal-r1-r2', 'VEDAL R1, R2', 'Системы реанимационные для новорождённых', 'Открытые реанимационные системы: круговой доступ к ребёнку, лучистый обогрев в ручном или сервоконтролируемом режиме, встроенные весы и пульсоксиметрия. У R2 дополнительно ЖК-дисплей, фототерапия, аспиратор и блок респираторной поддержки.', 'Открытые реанимационные системы для интенсивной терапии, экстренной помощи и выхаживания новорождённых. Круговой доступ к ребёнку для хирургических, диагностических и реанимационных процедур, температура поддерживается верхним лучистым обогревом.', 'confirmed', true, 0, '/photos/products/vedal-r1-r2.jpg', 'Открытая реанимационная система VEDAL');
