insert into product (id, slug, name, kind, summary, detail, doc_status, published, sort_order, image_src, image_alt) values ('de9e2ae2-2dff-47ba-a972-fcbf08e2fce9', 'vedal-a-2000', 'VEDAL A-2000', 'Инкубатор-трансформер', 'Совмещает инкубатор закрытого типа и открытую реанимационную систему. Переход между режимами электромеханическими приводами, без перекладывания новорождённого. Каналы мониторинга: пульсоксиметрия, ЭКГ, дыхание, НИАД, капнометрия.', 'Совмещает инкубатор закрытого типа и открытую реанимационную систему. Переход между режимами выполняют электромеханические приводы — новорождённого не нужно перекладывать.', 'confirmed', true, 1, '/photos/products/vedal-a-2000.jpg', 'Инкубатор-трансформер VEDAL A-2000');
