insert into product (id, slug, name, kind, summary, detail, doc_status, published, sort_order, image_src, image_alt) values ('e1812735-3ac2-4bb0-b305-b60e5e334726', 'vedal-t-100', 'VEDAL Т-100', 'Система терморегулирующая', 'Прокачивает подогретую или охлаждённую воду в терморегулирующее одеяло и удерживает температуру по показаниям датчиков пациента. Диапазон регулирования жидкости 12–39 °C, два размера одеял.', 'Прокачивает подогретую или охлаждённую воду в терморегулирующее одеяло на теле новорождённого и удерживает температуру по показаниям датчиков пациента. Применяется в отделениях неонатологии, реанимации и интенсивной терапии.', 'confirmed', true, 2, '/photos/products/vedal-t-100.jpg', 'Система терморегулирующая VEDAL Т-100');
